-- New brewing water (measured 24 Nov 2026): update recipe water profiles and
-- salts as decided per recipe in New_brewing_water_effect_on_recipes_2026-11-25.xlsx.
--   Option A: salts unchanged; stored profile = old profile + change of the water.
--   Option B: CaCl2 / CaSO4 / MgSO4 lowered to keep Cl, SO4 and Mg on target.
--             Each salt's Mash/Boil lines are scaled by the same factor; lines
--             that drop to 0 are removed. Profile = the resulting profile.
--   Alkalinity (where stored) +29.4 in both options. Acid doses are unchanged.
-- Every recipe gets a minor version and a revision entry (agreed with Jaap).
-- Skipped: 'Adjusted manually' recipes and the two B recipes without a B
-- calculation (265 Hannes Pale Ale (Briljant) 40, 290 Imperial Oatmeal Stout 25).
-- Idempotent: a recipe is only changed while it is still at the exported
-- version; a salt line only while it still holds the old quantity.
create temporary table _water_recipe (id bigint, opt text, vmaj int, vmin int, ca numeric, mg numeric, na numeric, cl numeric, so4 numeric, ratio numeric, alk numeric,
  cacl_old numeric, cacl_new numeric, caso4_old numeric, caso4_new numeric, mgso4_old numeric, mgso4_new numeric);

create temporary table _water_line (id bigint, recipe_id bigint, old_q numeric, new_q numeric);

-- Only recipes still at the exported version and active.
delete from _water_recipe w where not exists (
  select 1 from public.recipes r where r.id = w.id and r.status = 'active' and r.version_major = w.vmaj and r.version_minor = w.vmin);

update public.recipe_water rw
set ca = w.ca, mg = w.mg, na = w.na, cl = w.cl, so4 = w.so4, ratio_cl_so4 = w.ratio,
    alkalinity = coalesce(w.alk, rw.alkalinity)
from _water_recipe w where rw.recipe_id = w.id;

update public.recipe_ingredients ri set quantity = l.new_q
from _water_line l join _water_recipe w on w.id = l.recipe_id
where ri.id = l.id and ri.quantity = l.old_q and l.new_q is not null;

delete from public.recipe_ingredients ri
using _water_line l join _water_recipe w on w.id = l.recipe_id
where ri.id = l.id and ri.quantity = l.old_q and l.new_q is null;

select w.id, date '2026-11-25', 'Jaap Litjens',
  case when w.opt = 'A' then 'Water profile updated to the new brewing water (measured 24 Nov 2026); salts unchanged'
  else 'Salts adjusted to the new brewing water (measured 24 Nov 2026): '
    || concat_ws(', ',
         case when w.cacl_old <> w.cacl_new then 'CaCl2 ' || w.cacl_old || ' -> ' || w.cacl_new end,
         case when w.caso4_old <> w.caso4_new then 'CaSO4 ' || w.caso4_old || ' -> ' || w.caso4_new end,
         case when w.mgso4_old <> w.mgso4_new then 'MgSO4 ' || w.mgso4_old || ' -> ' || w.mgso4_new end)
    || ' g/hl; water profile updated' end,
  w.vmaj, w.vmin + 1, u.id
from _water_recipe w cross join (select id from public.users where name = 'Jaap Litjens') u;

update public.recipes r
set version_minor = w.vmin + 1, updated_by = (select id from public.users where name = 'Jaap Litjens')
from _water_recipe w where r.id = w.id;

drop table _water_recipe, _water_line;
